parameters.jsCode:
const input = $json.body ?? $json;

const heartbeat = input.heartbeat ?? {};
const monitor = input.monitor ?? {};
const rawStatus = heartbeat.status;

const statusMap = {
  0: 'down',
  1: 'up',
  2: 'pending',
  3: 'maintenance',
};

const normalizedStatus = statusMap[rawStatus] ?? 'unknown';

const tagNames = Array.isArray(monitor.tags)
  ? monitor.tags
      .map(tag => String(tag.name ?? tag.value ?? '').toUpperCase())
      .filter(Boolean)
  : [];

let severity = 'warning';

if (tagNames.includes('CRITICAL')) {
  severity = 'critical';
} else if (tagNames.includes('ERROR')) {
  severity = 'error';
} else if (tagNames.includes('WARNING')) {
  severity = 'warning';
}

let event = 'service_status_unknown';
let eventStatus = 'active';
let requiresAttention = false;

if (normalizedStatus === 'down') {
  event = 'service_down';
  eventStatus = 'active';
  requiresAttention = true;
}

if (normalizedStatus === 'up') {
  event = 'service_recovered';
  eventStatus = 'healthy';
  requiresAttention = false;
}

if (normalizedStatus === 'pending') {
  event = 'service_pending';
  eventStatus = 'pending';
}

if (normalizedStatus === 'maintenance') {
  event = 'service_maintenance';
  eventStatus = 'maintenance';
}

const monitorName = monitor.name ?? 'Unknown Service';

const heartbeatMessage = heartbeat.msg ?? null;

let normalizedMessage;

if (normalizedStatus === 'down') {
  normalizedMessage = heartbeatMessage
    ? `${monitorName} está indisponível. Motivo: ${heartbeatMessage}`
    : `${monitorName} está indisponível.`;
} else if (normalizedStatus === 'up') {
  normalizedMessage = `${monitorName} voltou a responder normalmente.${heartbeatMessage ? ` Resposta: ${heartbeatMessage}` : ''}`;
} else if (normalizedStatus === 'pending') {
  normalizedMessage = `${monitorName} está em estado de verificação.`;
} else if (normalizedStatus === 'maintenance') {
  normalizedMessage = `${monitorName} está em manutenção.`;
} else {
  normalizedMessage = input.msg ?? `${monitorName} mudou para ${normalizedStatus}.`;
}

return [{
  json: {
    source: 'uptime_kuma',
    severity,
    component: 'service_monitoring',
    event,
    status: eventStatus,
    timestamp: heartbeat.time ?? new Date().toISOString(),

    message: normalizedMessage,

    details: {
      monitor_id: monitor.id ?? heartbeat.monitorID ?? null,
      monitor_name: monitorName,
      monitor_type: monitor.type ?? null,
      kuma_status: normalizedStatus,
      kuma_status_code: rawStatus ?? null,
      ping_ms: heartbeat.ping ?? null,
      duration: heartbeat.duration ?? null,
      retries: heartbeat.retries ?? null,
      important: heartbeat.important ?? null,
      tags: tagNames,
    },

    requires_attention: requiresAttention,

    suggested_action:
      normalizedStatus === 'down'
        ? `Verificar o serviço ${monitorName}, seus logs e dependências no OMEAB.`
        : normalizedStatus === 'up'
          ? `Nenhuma ação imediata necessária. O serviço ${monitorName} voltou a responder normalmente.`
          : null,

    service: {
      id: monitor.id ?? heartbeat.monitorID ?? null,
      name: monitorName,
      type: monitor.type ?? null,
      status: normalizedStatus,
      ping_ms: heartbeat.ping ?? null,
    },

    raw: {
      heartbeat_msg: heartbeat.msg ?? null,
      kuma_msg: input.msg ?? null,
    },
  },
}];

const data = $json;

const previousEvent = data.previous_event ?? null;
const previousSeverity = data.previous_severity ?? null;
const previousStatus = data.previous_status ?? null;

const currentEvent = data.event;
const currentSeverity = data.severity;
const currentStatus = data.status;

let shouldNotify = false;
let reason = 'no_change';

// 1. Primeiro DOWN conhecido desse serviço
if (
  currentEvent === 'service_down' &&
  previousEvent === null
) {
  shouldNotify = true;
  reason = 'first_incident';
}

// 2. Serviço recuperou
else if (
  currentEvent === 'service_recovered' &&
  previousEvent !== null &&
  previousStatus !== 'healthy'
) {
  shouldNotify = true;
  reason = 'recovered';
}

// 3. O tipo do incidente mudou
else if (
  currentEvent === 'service_down' &&
  previousEvent !== null &&
  currentEvent !== previousEvent
) {
  shouldNotify = true;
  reason = 'incident_changed';
}

// 4. Mesmo incidente, mas severidade aumentou
else if (
  currentEvent === 'service_down' &&
  previousEvent !== null &&
  currentEvent === previousEvent
) {
  const severityRank = {
    info: 1,
    warning: 2,
    error: 3,
    critical: 4,
  };

  const currentRank = severityRank[currentSeverity] ?? 0;
  const previousRank = severityRank[previousSeverity] ?? 0;

  if (currentRank > previousRank) {
    shouldNotify = true;
    reason = 'severity_escalated';
  }
}

return [
  {
    json: {
      ...data,

      notification: {
        should_notify: shouldNotify,
        reason,

        previous_event: previousEvent,
        previous_severity: previousSeverity,
        previous_status: previousStatus,

        current_event: currentEvent,
        current_severity: currentSeverity,
        current_status: currentStatus,
      },
    },
  },
];

parameters.jsonBody:
={{
{
  source: $json.source,
  severity: $json.severity,
  component: $json.component,
  event: $json.event,
  status: $json.status,
  timestamp: $json.timestamp,
  message: $json.message,
  details: {
    ...$json.details,
    notification_reason: $json.notification?.reason ?? null
  },
  requires_attention: $json.requires_attention,
  suggested_action: $json.suggested_action
}
}}
